//! Types describing an AWS AMI registration payload (the arguments
//! to `RegisterImage`). Parses from TOML.
//!
//! Example:
//!
//! ```toml
//! name = "my-ami-name"
//! virtualization-type = "hvm"
//!
//! [block-device-mappings."/dev/xvda".ebs]
//! volume-type = "gp3"
//! volume-size = 4
//! ```
//!
//! Ported (trimmed) from `old-twoliter/tools/amispec/src/lib.rs`. The
//! old crate carried a parallel `TemplatedAmiSpec` type (generated by
//! the `serde-templated` proc-macro) so that a handlebars-templated
//! on-disk amispec could be rendered into this concrete one. We drop
//! that layer entirely: the new `mk_amispec` pipeline
//! (`crates/twoliter/src/variant/publish/register/mk_amispec.rs`)
//! runs `handlebars::render_template` on the raw TOML *text* first,
//! then hands the rendered text to `toml::from_str::<AmiSpec>`. The
//! user-facing `{{ foo }}` contract is preserved without a proc-macro
//! and a twin type for every field.
//!
//! The following AMI registration properties used for PV or S3-backed
//! AMIs are not supported: `ImageLocation`, `KernelId`, `RamdiskId`.
use aws_sdk_ec2::operation::register_image::RegisterImageInput;
use aws_sdk_ec2::operation::register_image::builders::RegisterImageInputBuilder;
use aws_sdk_ec2::types::BlockDeviceMapping as SdkBlockDeviceMapping;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;

pub mod ebs;

pub use ebs::{EbsBlockDevice, EbsBlockDeviceKind, InvalidValueError};

/// Possible device names are enumerated in the EC2 user guide.
pub type DeviceName = String;

/// The full amispec: a `RegisterImage` argument bundle, deserialized
/// from a TOML document produced by the `mk_amispec` merger.
#[derive(Debug, Clone, Default, Serialize, Deserialize, Eq, PartialEq)]
#[serde(deny_unknown_fields, rename_all = "kebab-case")]
pub struct AmiSpec {
    /// `#[serde(alias = "block-device-mapping")]` mirrors the old
    /// crate: the field is nominally plural, but user-authored files
    /// in the wild sometimes use the singular. Accept both.
    #[serde(default, alias = "block-device-mapping")]
    pub block_device_mappings: Option<HashMap<DeviceName, BlockDeviceMapping>>,

    pub name: String,
    pub architecture: Option<Architecture>,
    pub billing_product: Option<Vec<String>>,
    pub boot_mode: Option<BootMode>,
    pub description: Option<String>,
    pub ena_support: Option<bool>,
    pub imds_support: Option<ImdsSupport>,
    pub root_device_name: Option<String>,
    pub sriov_net_support: Option<SriovNetSupport>,
    pub tags: Option<HashMap<String, String>>,
    pub tpm_support: Option<TpmSupport>,
    pub uefi_data: Option<String>,
    pub virtualization_type: Option<VirtualizationType>,
}

impl AmiSpec {
    /// Translate this amispec into a `RegisterImageInputBuilder`
    /// pre-populated with every field the amispec sets. The caller
    /// still calls `.send_with(&ec2_client)` (or `.build()?.send(...)`).
    pub fn as_register_image_call(&self) -> RegisterImageInputBuilder {
        let AmiSpec {
            block_device_mappings,
            architecture,
            billing_product,
            boot_mode,
            description,
            ena_support,
            imds_support,
            name,
            root_device_name,
            sriov_net_support,
            tags,
            tpm_support,
            uefi_data,
            virtualization_type: _, // Only HVM is supported; hard-coded below.
        } = self;

        RegisterImageInput::builder()
            .name(name)
            // `amispec` only supports hvm images. `paravirtual` is the
            // RegisterImage default, so we always set it to `hvm` here.
            .virtualization_type(VirtualizationType::Hvm.to_string())
            .set_architecture(architecture.map(Into::into))
            .set_billing_products(billing_product.clone())
            .set_block_device_mappings(block_device_mappings.as_ref().map(|bdms| {
                // Sort by device name for a stable ordering in the
                // outgoing SDK request; tests rely on it and it makes
                // failures easier to diff.
                let mut entries: Vec<_> = bdms.iter().collect();
                entries.sort_by_key(|(name, _)| name.as_str());
                entries
                    .into_iter()
                    .map(|(device_name, bdm)| bdm.create_sdk_block_device_mapping(device_name))
                    .collect()
            }))
            .set_boot_mode(boot_mode.map(Into::into))
            .set_description(description.clone())
            .set_ena_support(*ena_support)
            .set_imds_support(imds_support.map(Into::into))
            .set_root_device_name(root_device_name.clone())
            .set_sriov_net_support(sriov_net_support.map(|s| s.to_string()))
            .set_tpm_support(tpm_support.map(Into::into))
            .set_uefi_data(uefi_data.clone())
            .set_tag_specifications(tags.as_ref().map(|tags| {
                // Sort tags by key so the tag list is deterministic.
                let mut sorted: Vec<_> = tags.iter().collect();
                sorted.sort_by_key(|(k, _)| *k);
                vec![
                    aws_sdk_ec2::types::TagSpecification::builder()
                        .resource_type(aws_sdk_ec2::types::ResourceType::Image)
                        .set_tags(Some(
                            sorted
                                .into_iter()
                                .map(|(k, v)| {
                                    aws_sdk_ec2::types::Tag::builder().key(k).value(v).build()
                                })
                                .collect(),
                        ))
                        .build(),
                ]
            }))
    }
}

#[derive(Debug, Copy, Clone, Serialize, Deserialize, Eq, PartialEq)]
#[serde(rename_all = "snake_case")]
pub enum Architecture {
    I386,
    X86_64,
    #[serde(alias = "aarch64")]
    Arm64,
    X86_64Mac,
    #[serde(alias = "aarch64_mac")]
    Arm64Mac,
}
serde_plain::derive_fromstr_from_deserialize!(Architecture);
serde_plain::derive_display_from_serialize!(Architecture);

impl From<Architecture> for aws_sdk_ec2::types::ArchitectureValues {
    fn from(value: Architecture) -> Self {
        match value {
            Architecture::I386 => Self::I386,
            Architecture::X86_64 => Self::X8664,
            Architecture::Arm64 => Self::Arm64,
            Architecture::X86_64Mac => Self::X8664Mac,
            Architecture::Arm64Mac => Self::Arm64Mac,
        }
    }
}

#[derive(Debug, Copy, Clone, Serialize, Deserialize, Eq, PartialEq)]
#[serde(rename_all = "kebab-case")]
pub enum BootMode {
    LegacyBios,
    Uefi,
    UefiPreferred,
}
serde_plain::derive_fromstr_from_deserialize!(BootMode);
serde_plain::derive_display_from_serialize!(BootMode);

impl From<BootMode> for aws_sdk_ec2::types::BootModeValues {
    fn from(value: BootMode) -> Self {
        match value {
            BootMode::LegacyBios => Self::LegacyBios,
            BootMode::Uefi => Self::Uefi,
            BootMode::UefiPreferred => Self::UefiPreferred,
        }
    }
}

#[derive(Debug, Copy, Clone, Serialize, Deserialize, Eq, PartialEq)]
pub enum ImdsSupport {
    #[serde(rename = "v2.0")]
    V2_0,
}
serde_plain::derive_fromstr_from_deserialize!(ImdsSupport);
serde_plain::derive_display_from_serialize!(ImdsSupport);

impl From<ImdsSupport> for aws_sdk_ec2::types::ImdsSupportValues {
    fn from(value: ImdsSupport) -> Self {
        match value {
            ImdsSupport::V2_0 => Self::V20,
        }
    }
}

#[derive(Debug, Copy, Clone, Serialize, Deserialize, Eq, PartialEq)]
pub enum TpmSupport {
    #[serde(rename = "v2.0")]
    V2_0,
}
serde_plain::derive_fromstr_from_deserialize!(TpmSupport);
serde_plain::derive_display_from_serialize!(TpmSupport);

impl From<TpmSupport> for aws_sdk_ec2::types::TpmSupportValues {
    fn from(value: TpmSupport) -> Self {
        match value {
            TpmSupport::V2_0 => Self::V20,
        }
    }
}

#[derive(Debug, Copy, Clone, Serialize, Deserialize, Eq, PartialEq)]
#[serde(rename_all = "lowercase")]
pub enum SriovNetSupport {
    Simple,
}
serde_plain::derive_fromstr_from_deserialize!(SriovNetSupport);
serde_plain::derive_display_from_serialize!(SriovNetSupport);

#[derive(Debug, Copy, Clone, Serialize, Deserialize, Eq, PartialEq)]
#[serde(rename_all = "lowercase")]
pub enum VirtualizationType {
    Hvm,
    // Paravirtual is not supported.
}
serde_plain::derive_fromstr_from_deserialize!(VirtualizationType);
serde_plain::derive_display_from_serialize!(VirtualizationType);

/// A single entry in the amispec's `block-device-mappings` map.
///
/// EBS-backed and virtual-name-backed mappings are both representable
/// here; the SDK builder in `create_sdk_block_device_mapping` selects
/// on which fields are set.
#[derive(Debug, Clone, Default, Serialize, Deserialize, Eq, PartialEq)]
#[serde(deny_unknown_fields, rename_all = "kebab-case")]
pub struct BlockDeviceMapping {
    pub ebs: Option<EbsBlockDevice>,
    pub no_device: Option<String>,
    pub virtual_name: Option<String>,
}

impl BlockDeviceMapping {
    pub(crate) fn create_sdk_block_device_mapping(
        &self,
        device_name: impl Into<String>,
    ) -> SdkBlockDeviceMapping {
        SdkBlockDeviceMapping::builder()
            .set_ebs(
                self.ebs
                    .as_ref()
                    .map(|block_device| block_device.create_sdk_ebs_block_device()),
            )
            .set_no_device(self.no_device.clone())
            .set_virtual_name(self.virtual_name.clone())
            .device_name(device_name.into())
            .build()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A minimal amispec parses and renders into a `RegisterImage`
    /// input with only `name` + the hard-coded `virtualization-type =
    /// hvm` set.
    #[test]
    fn parse_minimal() {
        let toml_str = r#"name = "minimal""#;
        let spec: AmiSpec = toml::from_str(toml_str).unwrap();
        assert_eq!(spec.name, "minimal");
        let built = spec.as_register_image_call().build().unwrap();
        assert_eq!(built.name.as_deref(), Some("minimal"));
        assert_eq!(built.virtualization_type.as_deref(), Some("hvm"));
    }

    /// A full amispec with an EBS root block-device parses, and the
    /// `as_register_image_call` output propagates every field.
    #[test]
    fn parse_with_root_ebs() {
        let toml_str = r#"
name = "my-ami"
architecture = "x86_64"
root-device-name = "/dev/xvda"
boot-mode = "uefi-preferred"
description = "a very cool ami"
ena-support = true
sriov-net-support = "simple"
virtualization-type = "hvm"

[block-device-mappings."/dev/xvda".ebs]
volume-type = "gp3"
delete-on-termination = true
snapshot-id = "snap-12345678"
volume-size = 4
"#;
        let spec: AmiSpec = toml::from_str(toml_str).unwrap();
        assert_eq!(spec.name, "my-ami");
        assert_eq!(spec.architecture, Some(Architecture::X86_64));
        assert_eq!(spec.boot_mode, Some(BootMode::UefiPreferred));
        let built = spec.as_register_image_call().build().unwrap();
        assert_eq!(
            built.architecture,
            Some(aws_sdk_ec2::types::ArchitectureValues::X8664)
        );
        assert_eq!(built.description.as_deref(), Some("a very cool ami"));
        assert_eq!(
            built
                .block_device_mappings
                .as_ref()
                .and_then(|m| m.first())
                .and_then(|bdm| bdm.device_name.as_deref()),
            Some("/dev/xvda")
        );
    }

    /// Singular `[block-device-mapping."…"]` is accepted as an alias
    /// for the plural form.
    #[test]
    fn parse_singular_block_device_mapping_alias() {
        let toml_str = r#"
name = "singular"
[block-device-mapping."/dev/xvda".ebs]
volume-type = "gp2"
"#;
        let spec: AmiSpec = toml::from_str(toml_str).unwrap();
        assert!(
            spec.block_device_mappings
                .as_ref()
                .and_then(|m| m.get("/dev/xvda"))
                .is_some()
        );
    }

    /// Out-of-range `volume-size` on `st1` (bounds are 125..=16384)
    /// is rejected at deserialize time by `bounded-integer`.
    #[test]
    fn reject_volume_size_below_st1_bound() {
        let toml_str = r#"
name = "too-small-st1"
[block-device-mappings."/dev/xvda".ebs]
volume-type = "st1"
volume-size = 10
"#;
        assert!(toml::from_str::<AmiSpec>(toml_str).is_err());
    }

    /// Unknown top-level attributes are rejected by
    /// `deny_unknown_fields` — a typo in an on-disk `--amispec-file`
    /// fails loudly rather than silently.
    #[test]
    fn reject_unknown_top_level_field() {
        let toml_str = r#"
name = "typo"
what = "is this"
"#;
        assert!(toml::from_str::<AmiSpec>(toml_str).is_err());
    }

    /// Tag serialization is deterministic (sorted by key) so the
    /// generated `RegisterImage` input diffs cleanly.
    #[test]
    fn tags_render_in_sorted_order() {
        let toml_str = r#"
name = "tagged"
[tags]
Zone = "z"
Environment = "prod"
Application = "app"
"#;
        let spec: AmiSpec = toml::from_str(toml_str).unwrap();
        let built = spec.as_register_image_call().build().unwrap();
        let tag_specs = built.tag_specifications.expect("tag specs present");
        let tags = tag_specs[0].tags.as_ref().unwrap();
        let keys: Vec<&str> = tags.iter().filter_map(|t| t.key.as_deref()).collect();
        assert_eq!(keys, vec!["Application", "Environment", "Zone"]);
    }
}
